What does this code print? What do the numbers mean, and would they still be the shortest distances if each edge had a different length?

from collections import deque
graph = {"A": ["B", "C"], "B": ["E"], "C": ["D"], "D": ["E"], "E": ["F"], "F": []}

def bfs(start):
    dist = {start: 0}
    q = deque([start])
    while q:
        node = q.popleft()
        for nb in graph[node]:
            if nb not in dist:
                dist[nb] = dist[node] + 1
                q.append(nb)
    return dist

print(bfs("A"))

This class simulates how a dynamic array such as a Python list grows: when it is full, it moves every item into a new block twice as large and counts the moved items. What does it print? What do the numbers tell you about the cost of a single append and of n appends?

class DynArray:
    def __init__(self):
        self.size, self.cap, self.copies = 0, 1, 0

    def append(self, x):
        if self.size == self.cap:
            self.copies += self.size  # move every item to a bigger block
            self.cap *= 2
        self.size += 1

for n in [16, 17, 1000]:
    arr = DynArray()
    for i in range(n):
        arr.append(i)
    print(n, arr.cap, arr.copies)
